```section
<section id="hero" aria-labelledby="hero-title">
<style>
#hero{background:var(--j2-secondary,#0B1F3A);color:#fff;padding:96px 16px 48px;scroll-margin-top:64px;overflow:hidden;box-sizing:border-box}
#hero *{box-sizing:border-box;min-width:0}
#hero .hero-inner{max-width:1100px;margin:0 auto;display:grid;gap:32px;grid-template-columns:1fr;align-items:center}
#hero .hero-kicker{display:inline-block;margin:0 0 12px;padding:6px 12px;border-radius:999px;background:var(--j2-accent,#FF6B2C);color:#14122B;font-weight:700;font-size:.875rem}
#hero h1{margin:0 0 12px;font-family:var(--j2-font-heading,sans-serif);font-size:clamp(2rem,9vw,3.75rem);line-height:1.1;overflow-wrap:anywhere}
#hero .hero-lead{margin:0 0 8px;font-size:1.125rem;line-height:1.5}
#hero .hero-meta{list-style:none;margin:16px 0 24px;padding:0;display:grid;gap:8px;font-size:1rem;line-height:1.5}
#hero .hero-meta li{overflow-wrap:anywhere}
#hero .hero-meta strong{color:#FFB38F}
#hero .photo-placeholder{display:flex;align-items:center;justify-content:center;text-align:center;min-height:200px;width:100%;border:2px dashed #FFB38F;border-radius:var(--j2-radius,12px);background:rgba(255,255,255,.08);color:#fff;font-weight:600;padding:16px}
#hero .cd-wrap{margin-top:24px}
#hero .cd-label{margin:0 0 8px;font-weight:600;font-size:.9375rem}
#hero #countdown{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;max-width:420px}
#hero .cd-box{background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.3);border-radius:var(--j2-radius,12px);padding:12px 4px;text-align:center}
#hero .cd-num{display:block;font-family:var(--j2-font-heading,sans-serif);font-size:clamp(1.5rem,7vw,2.5rem);font-weight:700;line-height:1.1;color:#FFB38F;font-variant-numeric:tabular-nums}
#hero .cd-unit{display:block;font-size:.75rem;text-transform:uppercase;letter-spacing:.06em}
@media (min-width:860px){
#hero{padding:112px 24px 72px}
#hero .hero-inner{grid-template-columns:1.1fr .9fr;gap:48px}
#hero .photo-placeholder{min-height:340px}
}
</style>
<div class="hero-inner">
<div class="hero-text">
<p class="hero-kicker">Students and professionals welcome</p>
<h1 id="hero-title">CodeSprint Pune 2027</h1>
<p class="hero-lead">A two-day hackathon in Pune.</p>
<ul class="hero-meta">
<li><strong>Day one:</strong> Saturday 6 March 2027</li>
<li><strong>Day two:</strong> Sunday 7 March 2027</li>
<li><strong>Venue:</strong> Lakeside Tech Hall, 12 Lake Road, Pune 411002</li>
</ul>
<a class="j2-btn" href="#register">Register your team</a>
<div class="cd-wrap">
<p class="cd-label" id="cd-label">Hackathon starts in</p>
<div id="countdown" role="timer" aria-labelledby="cd-label">
<div class="cd-box"><span class="cd-num" id="cd-days">00</span><span class="cd-unit">Days</span></div>
<div class="cd-box"><span class="cd-num" id="cd-hours">00</span><span class="cd-unit">Hours</span></div>
<div class="cd-box"><span class="cd-num" id="cd-mins">00</span><span class="cd-unit">Mins</span></div>
<div class="cd-box"><span class="cd-num" id="cd-secs">00</span><span class="cd-unit">Secs</span></div>
</div>
</div>
</div>
<div class="photo-placeholder" role="img" aria-label="Event photo placeholder">Event photo placeholder</div>
</div>
<script>
(function(){
var target=new Date('2027-03-06T10:00:00+05:30').getTime();
var d=document.getElementById('cd-days'),h=document.getElementById('cd-hours'),m=document.getElementById('cd-mins'),s=document.getElementById('cd-secs');
if(!d||!h||!m||!s){return;}
function pad(n){return n<10?'0'+n:String(n);}
function tick(){
var diff=Math.max(0,target-Date.now());
var total=Math.floor(diff/1000);
d.textContent=pad(Math.floor(total/86400));
h.textContent=pad(Math.floor(total%86400/3600));
m.textContent=pad(Math.floor(total%3600/60));
s.textContent=pad(total%60);
}
tick();
setInterval(tick,1000);
})();
</script>
</section>
