<section id="fees" aria-labelledby="fees-title">
<style>
#fees{padding:var(--j2-section,64px) 16px;scroll-margin-top:64px;box-sizing:border-box;overflow:hidden}
#fees *{box-sizing:border-box;min-width:0}
