#fees h2{margin:0 0 8px;font-family:var(--j2-font-heading,sans-serif);font-size:clamp(1.75rem,6vw,2.5rem);line-height:1.15;color:var(--j2-secondary,#0B1F3A)}
#fees .fees-intro{margin:0 0 32px;color:var(--j2-muted,#55526E);font-size:1.0625rem;line-height:1.5}
#fees .fees-grid{display:grid;grid-template-columns:1fr;gap:24px}
#fees .fees-card h3{margin:0 0 16px;font-family:var(--j2-font-heading,sans-serif);font-size:1.375rem;line-height:1.2;color:var(--j2-primary,#4F2BD9)}
#fees .price-list{margin:0 0 16px;padding:0;list-style:none;display:grid;gap:8px}
#fees .price-list li{padding:12px 0;border-top:1px solid #DAD6F0;font-size:1.0625rem;font-weight:600;line-height:1.4;overflow-wrap:anywhere}
