#fees .rule-note{margin:0;padding:12px 16px;border-left:6px solid var(--j2-accent,#FF6B2C);background:var(--j2-background,#F7F7FB);border-radius:var(--j2-radius,12px);line-height:1.5;color:var(--j2-text,#14122B)}
