#fees .hint{font-size:.875rem;color:var(--j2-muted,#55526E);line-height:1.4}
#fees select,#fees input{width:100%;min-height:48px;padding:10px 12px;font:inherit;font-size:1rem;color:var(--j2-text,#14122B);background:var(--j2-surface,#FFFFFF);border:2px solid #DAD6F0;border-radius:var(--j2-radius,12px)}
#fees select:focus,#fees input:focus{outline:3px solid var(--j2-primary,#4F2BD9);outline-offset:2px;border-color:var(--j2-primary,#4F2BD9)}
#fees .total-box{margin-top:8px;padding:16px;border-radius:var(--j2-radius,12px);background:var(--j2-secondary,#0B1F3A);color:#fff}
#fees .total-label{margin:0 0 4px;font-size:.9375rem;font-weight:600}
#fees #calc-total{display:block;font-family:var(--j2-font-heading,sans-serif);font-size:clamp(2rem,9vw,3rem);font-weight:700;line-height:1.1;color:#FFB38F;font-variant-numeric:tabular-nums}
#fees .breakdown{margin:12px 0 0;padding:0;list-style:none;display:grid;gap:4px;font-size:.9375rem;line-height:1.4}
#fees .breakdown li{overflow-wrap:anywhere}
#fees .fees-action{margin-top:24px;display:flex;flex-wrap:wrap;gap:16px;align-items:center}
@media (min-width:860px){
