#fees .fees-grid{grid-template-columns:1fr 1fr;gap:32px;align-items:start}
}
</style>
<div class="fees-inner">
<h2 id="fees-title">Work out what you will pay</h2>
<p class="fees-intro">Choose your ticket, team size and meal passes to see the total.</p>
<div class="fees-grid">
<div class="j2-card fees-card">
<h3>Prices</h3>
<ul class="price-list">
<li>Student Rs 400 per participant</li>
<li>Professional Rs 800 per participant</li>
<li>Meal pass Rs 200 each, optional</li>
</ul>
<p class="rule-note">Early-bird: 10% off entry fees only, not meal passes, for registrations up to 15 February 2027.</p>
</div>
<div class="j2-card fees-card">
<h3>Fee calculator</h3>
<form id="calc-form" onsubmit="return false" novalidate>
<div class="field">
<label for="calc-ticket">Ticket type</label>
<select id="calc-ticket" name="ticket">
<option value="Student">Student</option>
<option value="Professional">Professional</option>
</select>
</div>
<div class="field">
<label for="calc-people">Number of participants</label>
<input id="calc-people" name="people" type="number" min="1" max="4" step="1" value="1" inputmode="numeric">
<span class="hint">1 to 4 participants</span>
</div>
<div class="field">
<label for="calc-meals">Number of meal passes</label>
<input id="calc-meals" name="meals" type="number" min="0" max="4" step="1" value="0" inputmode="numeric">
<span class="hint">0 to 4 meal passes</span>
</div>
<div class="field">
<label for="calc-date">Registration date</label>
<input id="calc-date" name="date" type="date">
<span class="hint">Pick the date you will register. Without a date, the regular price is shown.</span>
</div>
<div class="total-box">
<p class="total-label" id="calc-total-label">Your total</p>
<output id="calc-total" for="calc-ticket calc-people calc-meals calc-date" aria-labelledby="calc-total-label">Rs 400</output>
<ul class="breakdown" id="calc-breakdown" aria-live="polite"></ul>
</div>
</form>
</div>
</div>
<div class="fees-action">
<a class="j2-btn" href="#register">Register your team</a>
</div>
</div>
<script>
(function(){
var ticket=document.getElementById('calc-ticket'),
people=document.getElementById('calc-people'),
meals=document.getElementById('calc-meals'),
date=document.getElementById('calc-date'),
total=document.getElementById('calc-total'),
list=document.getElementById('calc-breakdown');
if(!ticket||!people||!meals||!date||!total||!list){return;}
var PRICE={Student:400,Professional:800},MEAL=200,CUTOFF='2027-02-15';
function clamp(v,lo,hi){var n=parseInt(v,10);if(isNaN(n)){n=lo;}return Math.min(hi,Math.max(lo,n));}
function rs(n){return 'Rs '+(Math.round(n*100)/100);}
function add(text){var li=document.createElement('li');li.textContent=text;list.appendChild(li);}
function calc(){
var t=PRICE[ticket.value]?ticket.value:'Student';
var p=clamp(people.value,1,4),m=clamp(meals.value,0,4);
var entry=PRICE[t]*p,mealCost=MEAL*m,discount=0;
var early=!!date.value&&date.value<=CUTOFF;
if(early){discount=Math.round(entry*10)/100;}
var sum=entry-discount+mealCost;
total.textContent=rs(sum);
list.innerHTML='';
add('Entry: '+p+' x '+t+' at '+rs(PRICE[t])+' = '+rs(entry));
if(early){add('Early-bird 10% off entry: minus '+rs(discount));}
else if(date.value){add('Early-bird has ended for this date, so no discount applies.');}
add('Meal passes: '+m+' x '+rs(MEAL)+' = '+rs(mealCost));
}
['input','change','keyup'].forEach(function(ev){
ticket.addEventListener(ev,calc);
people.addEventListener(ev,calc);
meals.addEventListener(ev,calc);
date.addEventListener(ev,calc);
});
people.addEventListener('change',function(){people.value=clamp(people.value,1,4);calc();});
meals.addEventListener('change',function(){meals.value=clamp(meals.value,0,4);calc();});
calc();
})();
</script>
</section>
