(function(){
var nav=document.getElementById('site-nav');
if(!nav){return;}
var list=nav.querySelector('.nav-list');
var links=nav.querySelectorAll('a[href^="#"]');
var items=[];
for(var i=0;i<links.length;i++){
var id=links[i].getAttribute('href').slice(1);
var el=document.getElementById(id);
if(el){items.push({link:links[i],el:el});}
}
if(!items.length){return;}
var last=null;
function setActive(item){
if(item===last){return;}
last=item;
for(var j=0;j<items.length;j++){
if(items[j]===item){
items[j].link.classList.add('active');
items[j].link.setAttribute('aria-current','true');
}else{
items[j].link.classList.remove('active');
items[j].link.removeAttribute('aria-current');
}
}
if(list&&list.scrollWidth>list.clientWidth){
var l=item.link;
list.scrollLeft=l.offsetLeft-(list.clientWidth-l.offsetWidth)/2;
}
}
function update(){
var current=items[0];
for(var k=0;k<items.length;k++){
if(items[k].el.getBoundingClientRect().top<=120){current=items[k];}
}
var doc=document.documentElement;
if(window.innerHeight+(window.pageYOffset||doc.scrollTop)>=doc.scrollHeight-4){
current=items[items.length-1];
}
setActive(current);
}
var ticking=false;
function onScroll(){
if(ticking){return;}
ticking=true;
(window.requestAnimationFrame||function(f){setTimeout(f,16);})(function(){ticking=false;update();});
}
window.addEventListener('scroll',onScroll,{passive:true});
window.addEventListener('resize',onScroll);
window.addEventListener('hashchange',onScroll);
window.addEventListener('load',update);
update();
})();
</script>
